package com.shms.entity;
import jakarta.persistence.*;
@Entity @Table(name="beds",uniqueConstraints=@UniqueConstraint(name="uk_bed_ward_number",columnNames={"ward_id","bed_number"})) public class Bed { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="ward_id",nullable=false) private Ward ward; @Column(name="bed_number",nullable=false) private String bedNumber; @Enumerated(EnumType.STRING) private BedType bedType=BedType.STANDARD; @Enumerated(EnumType.STRING) private Status status=Status.AVAILABLE; public enum BedType{STANDARD,ICU,PRIVATE,EMERGENCY} public enum Status{AVAILABLE,OCCUPIED,RESERVED,MAINTENANCE} public Long getId(){return id;} public void setId(Long v){id=v;} public Ward getWard(){return ward;} public void setWard(Ward v){ward=v;} public String getBedNumber(){return bedNumber;} public void setBedNumber(String v){bedNumber=v;} public BedType getBedType(){return bedType;} public void setBedType(BedType v){bedType=v;} public Status getStatus(){return status;} public void setStatus(Status v){status=v;} }
